CREATE TABLE "promo_sasaran" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "promo_sasaran_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id_promo" bigint NOT NULL,
	"id_barang" bigint,
	"id_kategori" bigint,
	"id_merk" bigint,
	CONSTRAINT "chk_promo_sasaran_satu" CHECK (num_nonnulls(id_barang, id_kategori, id_merk) = 1)
);
